<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Laporan Performa Sales</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;font-size:10px;color:#111}h1{text-align:center;font-size:18px;margin:0 0 4px}h2{font-size:12px;margin:14px 0 5px}.meta{text-align:center;color:#444;margin-bottom:16px}.summary{display:grid;grid-template-columns:repeat(6,1fr);gap:5px}.metric{border:1px solid #555;padding:7px}.metric span{display:block;font-size:9px;color:#555}.metric strong{display:block;font-size:15px;margin-top:3px}table{border-collapse:collapse;width:100%;margin-top:5px}th,td{border:1px solid #444;padding:4px;text-align:left;vertical-align:top}th{background:#eee;font-size:9px}td.number{text-align:center}.note{margin-top:14px;color:#555;font-size:9px}@media print{.no-print{display:none}}</style></head><body><h1>LAPORAN PERFORMA SALES</h1><div class="meta">Periode {{ $filters['date_from'] }} sampai {{ $filters['date_to'] }}</div><div class="summary"><div class="metric"><span>Total Agenda</span><strong>{{ $report['totals']['total_agenda'] }}</strong></div><div class="metric"><span>Agenda Selesai</span><strong>{{ $report['totals']['agenda_selesai'] }}</strong></div><div class="metric"><span>Total Lead</span><strong>{{ $report['totals']['total_lead'] }}</strong></div><div class="metric"><span>Tatap Muka</span><strong>{{ $report['totals']['tatap_muka'] }}</strong></div><div class="metric"><span>Cek Lokasi</span><strong>{{ $report['totals']['cek_lokasi'] }}</strong></div><div class="metric"><span>UTJ</span><strong>{{ $report['totals']['utj'] }}</strong></div></div><h2>REKAP SALES</h2><table><thead><tr><th>Sales</th><th>Koordinator</th><th>Proyek</th><th>Total Agenda</th><th>Agenda Selesai</th><th>Total Lead</th></tr></thead><tbody>@forelse($report['rows'] as $row)<tr><td>{{ $row['sales_name'] }}</td><td>{{ $row['coordinator_name'] }}</td><td>{{ $row['project_name'] }}</td><td class="number">{{ $row['total_agenda'] }}</td><td class="number">{{ $row['agenda_selesai'] }}</td><td class="number">{{ $row['total_lead'] }}</td></tr>@empty<tr><td colspan="6">Tidak ada data.</td></tr>@endforelse</tbody></table><h2>DETAIL LEAD</h2><table><thead><tr><th>Tanggal</th><th>ID Lead</th><th>Konsumen</th><th>Sales</th><th>Sumber / Kanal</th><th>Status</th></tr></thead><tbody>@forelse($report['leads'] as $lead)<tr><td>{{ $lead->tanggal_lead->format('d/m/Y') }}</td><td>{{ $lead->id_lead }}</td><td>{{ $lead->nama_konsumen }}</td><td>{{ $lead->salesPic->name }}</td><td>{{ $lead->sumber_lead }} / {{ $lead->kanal_masuk }}</td><td>{{ $lead->status_lead }}</td></tr>@empty<tr><td colspan="6">Tidak ada Lead.</td></tr>@endforelse</tbody></table><h2>DETAIL AGENDA</h2><table><thead><tr><th>Tanggal</th><th>Sales</th><th>Proyek</th><th>Kategori</th><th>Agenda / Hasil</th><th>Status</th></tr></thead><tbody>@forelse($report['agendas'] as $agenda)<tr><td>{{ $agenda->agenda_date->format('d/m/Y') }}</td><td>{{ $agenda->creator->name }}</td><td>{{ $agenda->lead?->project?->name ?? $agenda->salesCase?->lot?->project?->name ?? '-' }}</td><td>{{ $agenda->activity_category }}</td><td>{{ $agenda->title }}<br>{{ $agenda->activity_result ?: '-' }}</td><td>{{ $agenda->status }}</td></tr>@empty<tr><td colspan="6">Tidak ada Agenda.</td></tr>@endforelse</tbody></table><p class="note">Laporan ini merupakan rekap performa aktivitas. Nominal fee belum dihitung.</p><script>window.addEventListener('load',()=>window.print())</script></body></html>
